// apps/penplotter/src/active-layer-panel.js — the FILL-stage panel (PP-5). Replaces the PP-4b no-op stub.
// Edits the ACTIVE toolpath's outline{style,params} + fill{pattern,params} — the 2nd tab over the SAME
// state.toolpaths (Toolpath tab = pens/order/feeds; Fill tab = pattern/style). ADAPTED to the #core/plot
// object-registries: the Style/Pattern dropdowns come from OUTLINE_STYLES / FILL_PATTERNS, and the numeric controls
// are GENERATED by iterating the SELECTED entry's declared `params` ({key,label,type,default,unit,min,max}) — no
// hardcoded per-pattern forms (the declaration payoff). Single active toolpath (the original's bulk-edit is deferred).

import { state, activeToolpath } from "./state.js";
import { $ } from "./dom.js";
import { FILL_PATTERNS, fillPattern } from "#core/plot/fills/index.js";
import { OUTLINE_STYLES, outlineStyle } from "#core/plot/outlines/index.js";
import { snapshot } from "./history.js";

let triggerRerender = () => {};
export function installActiveLayerPanel(onChange) { triggerRerender = onChange || (() => {}); }

export function renderActiveLayerPanel() {
  const root = $("#activeLayerContent");
  if (!root) return;
  root.innerHTML = "";
  const tps = state.toolpaths || [];
  if (!tps.length) { root.appendChild(msg("No toolpaths — create one in the Toolpath tab.")); return; }

  root.appendChild(toolpathSelect(tps));      // pick which toolpath (shared state.activeToolpathId)
  const tp = activeToolpath() || tps[0];
  if (!tp) return;

  // OUTLINE — style dropdown + the selected style's declared params.
  root.appendChild(subhead("Outline"));
  root.appendChild(registrySelect("Style", tp.outline.style, OUTLINE_STYLES, false, (v) => { snapshot(); tp.outline.style = v; restructure(); }));
  const os = outlineStyle(tp.outline.style);
  if (os) for (const p of os.params) root.appendChild(paramField(p, tp.outline));

  // FILL — pattern dropdown (+ "None") + the selected pattern's declared params.
  root.appendChild(subhead("Fill"));
  root.appendChild(registrySelect("Pattern", tp.fill.pattern, FILL_PATTERNS, true, (v) => { snapshot(); tp.fill.pattern = v; restructure(); }));
  const fp = tp.fill.pattern && tp.fill.pattern !== "none" ? fillPattern(tp.fill.pattern) : null;
  if (fp) for (const p of fp.params) root.appendChild(paramField(p, tp.fill));
}

// Pattern/style change restructures which params show -> re-render the panel + recompute the overlay.
function restructure() { renderActiveLayerPanel(); triggerRerender(); }

function toolpathSelect(tps) {
  const wrap = field(); const label = document.createElement("label"); label.textContent = "Toolpath";
  const sel = document.createElement("select");
  for (const tp of tps) {
    const o = document.createElement("option"); o.value = tp.id; o.textContent = tp.name + " (" + tp.type + ")";
    if (tp.id === state.activeToolpathId) o.selected = true;
    sel.appendChild(o);
  }
  sel.onchange = () => { state.activeToolpathId = sel.value; restructure(); };
  wrap.append(label, sel); return wrap;
}

// A dropdown over a #core/plot registry (entries {id,label}); withNone prepends a "None" option (fill only).
function registrySelect(labelText, value, entries, withNone, onChange) {
  const wrap = field(); const label = document.createElement("label"); label.textContent = labelText;
  const sel = document.createElement("select");
  const opts = withNone ? [{ id: "none", label: "None" }].concat(entries) : entries;
  for (const e of opts) {
    const o = document.createElement("option"); o.value = e.id; o.textContent = e.label;
    if (e.id === value) o.selected = true;
    sel.appendChild(o);
  }
  sel.onchange = () => onChange(sel.value);
  wrap.append(label, sel); return wrap;
}

// GENERATE a numeric control from a declared param {key,label,type,default,unit,min,max}. All params are numeric today.
function paramField(p, obj) {
  const v = (obj[p.key] !== undefined && obj[p.key] !== null) ? obj[p.key] : p.default;
  const wrap = field();
  const label = document.createElement("label");
  label.innerHTML = p.label + (p.unit ? " <small>" + p.unit + "</small>" : "");
  const input = document.createElement("input");
  input.type = "number"; input.value = v; input.step = "any";
  if (p.min !== undefined) input.min = p.min;
  if (p.max !== undefined) input.max = p.max;
  const commit = () => {
    if (input.value === "") return;
    const val = +input.value;
    if (!Number.isFinite(val)) return;
    snapshot();
    obj[p.key] = val;
    triggerRerender();      // recompute + redraw the overlay (fill strokes update live)
  };
  input.oninput = commit; input.onchange = commit;
  wrap.append(label, input); return wrap;
}

function field() { const d = document.createElement("div"); d.className = "field"; return d; }
function subhead(t) { const d = document.createElement("div"); d.className = "subhead"; d.textContent = t; return d; }
function msg(t) { const d = document.createElement("div"); d.className = "empty"; d.textContent = t; return d; }
